import pytest


@pytest.fixture(autouse=True)
def _shelf_db(tmp_path, monkeypatch):
    monkeypatch.setenv("SHELF_DB", str(tmp_path / "shelf.db"))

"""The catalogue, in a sqlite file."""
import contextlib
import os
import sqlite3

_SCHEMA = (
    "CREATE TABLE IF NOT EXISTS books (title TEXT NOT NULL, author TEXT NOT NULL)",
    "CREATE TABLE IF NOT EXISTS loans (title TEXT PRIMARY KEY, member TEXT NOT NULL)",
)


class ShelfError(Exception):
    pass


class UnknownBook(ShelfError):
    pass


class AlreadyLent(ShelfError):
    pass


class NotLent(ShelfError):
    pass


def db_path():
    return os.environ.get("SHELF_DB", "shelf.db")


@contextlib.contextmanager
def _db():
    with contextlib.closing(sqlite3.connect(db_path(), timeout=30, isolation_level=None)) as con:
        for stmt in _SCHEMA:
            con.execute(stmt)
        yield con


def _rows(cur):
    return [{"title": t, "author": a} for t, a in cur]


def add(title, author):
    with _db() as con:
        con.execute("INSERT INTO books (title, author) VALUES (?, ?)", (title, author))
    return {"title": title, "author": author}


def find(query):
    with _db() as con:
        return _rows(con.execute(
            "SELECT title, author FROM books WHERE instr(title, ?) > 0 ORDER BY rowid", (query,)))


def all_books():
    with _db() as con:
        return _rows(con.execute("SELECT title, author FROM books ORDER BY rowid"))


def clear():
    with _db() as con:
        con.execute("DELETE FROM loans")
        con.execute("DELETE FROM books")


def lend(title, member):
    with _db() as con:
        con.execute("BEGIN IMMEDIATE")
        try:
            cur = con.execute(
                "INSERT INTO loans (title, member) SELECT ?, ? "
                "WHERE EXISTS (SELECT 1 FROM books WHERE title = ?)", (title, member, title))
        except sqlite3.IntegrityError:
            con.execute("ROLLBACK")
            raise AlreadyLent(title)
        if cur.rowcount == 0:
            con.execute("ROLLBACK")
            raise UnknownBook(title)
        con.execute("COMMIT")


def return_book(title):
    with _db() as con:
        if con.execute("DELETE FROM loans WHERE title = ?", (title,)).rowcount:
            return
        if con.execute("SELECT 1 FROM books WHERE title = ?", (title,)).fetchone() is None:
            raise UnknownBook(title)
        raise NotLent(title)


def holder(title):
    with _db() as con:
        row = con.execute("SELECT member FROM loans WHERE title = ?", (title,)).fetchone()
    return row[0] if row else None
